import Foundation

enum EmuScriptAssets {
    private static let stbvorbisBase64 = ""
    
    static let stbvorbisScript: String = {
        if let data = Data(base64Encoded: stbvorbisBase64),
           let str = String(data: data, encoding: .utf8) {
            return str
        }
        return ""
    }()
}
